			"client/bootstrapTests-client.ts"
		],
		plugins: [
			envPlugin(localEnv),
			resolveTestLibsPlugin(),
			...rollupDebugPlugins(path.resolve(".."), {outDir: "build"}),
			rollupPluginJson({}),
			nodeResolve({preferBuiltins: true}),
			sqliteNativeBannerPlugin(
				{
					environment: "node",
					platform: process.platform,
					rootDir: projectRoot,
					dstPath: buildDir("better_sqlite3.node")
				},
				log
			),
		],
	})
	return [
		{
			bundle,
			async generate() {
				await Promise.all([
					createUnitTestHtml(false, "api", localEnv, log),
					createUnitTestHtml(false, "client", localEnv, log)
				])

				const start = Date.now()
				log("Generating...")
				const result = await bundle.generate({sourceMap: true, dir: buildDir(), format: "esm", chunkFileNames: "[name].js"})
				log("Generated in", Date.now() - start)

				const writingStart = Date.now()
				await writeNollupBundle(result, log, buildDir())
				log("Wrote in ", Date.now() - writingStart)
			},
		}
	]
}

// We use this homebrew plugin so that libs are copies to _virtual folder and *not* build/node_modules
// (which would be the case with preserve_modules).
// Files in build/node_modules are treated as separate libraries and ES mode resets back to commonjs.
function resolveTestLibsPlugin() {
	return {
		name: "resolve-test-libs",
		resolveId(source, importer) {
			switch (source) {
				case "mithril/test-utils/browserMock":
					// This one is *not* a module, just a script so we need to rewrite import path.
					// nollup only rewrites absolute paths so resolve path first.
					return path.resolve("../node_modules/mithril/test-utils/browserMock.js")
				case "ospec":
					return "../node_modules/ospec/ospec.js"
				case "better-sqlite3":
				case "crypto":
				case "xhr2":
				case "express":
				case "server-destroy":
				case "body-parser":
				case "mockery":
				case "path":
				case "url":
				case "util":
				case "node-forge":
				case "os":
				case "electron-updater":
				case "child_process":
				case "querystring":
				case "events":
				case "fs":
				case "buffer":
				case "winreg":
				case "testdouble": // cannot bundle it now because nollup
					return false
				case "electron":
					throw new Error(`electron is imported by ${importer}, don't do it in tests`)
			}
		},
	}
}


/**
 * Simple plugin for virtual module "@tutanota/env" which resolves to the {@param env}.
 * see https://rollupjs.org/guide/en/#a-simple-example
 */
function envPlugin(env) {
	return {
		name: "tutanota-env",
		resolveId(source) {
			if (source === "@tutanota/env") return source
		},
		load(id) {
			if (id === "@tutanota/env") return `export default ${JSON.stringify(env)}`
		},
	}
}

async function createUnitTestHtml(watch, project, localEnv, log) {
	const imports = [{src: `test-${project}.js`, type: "module"}]


	const template = `import('./bootstrapTests-${project}.js')`
	const targetFile = buildDir(`test-${project}.html`)
	log(`Generating browser tests for ${project} at "${targetFile}"`)
	await _writeFile(buildDir(`test-${project}.js`), [
		`window.whitelabelCustomizations = null`,
		`window.env = ${JSON.stringify(localEnv, null, 2)}`,
		watch ? "new WebSocket('ws://localhost:8080').addEventListener('message', (e) => window.hotReload())" : "",
	].join("\n") + "\n" + template)

	const html = await renderHtml(imports, localEnv)
	await _writeFile(targetFile, html)
}

function _writeFile(targetFile, content) {
	return fs.mkdir(path.dirname(targetFile), {recursive: true}).then(() => fs.writeFile(targetFile, content, 'utf-8'))
}

function buildDir(...files) {
	return path.join(testRoot, "build", ...files)
}

import {client} from "./ClientDetector"
import type {Base64} from "@tutao/tutanota-utils"
import {base64ToUint8Array, uint8ArrayToBase64} from "@tutao/tutanota-utils"
import type {LanguageCode} from "./LanguageViewModel"
import type {ThemeId} from "../gui/theme"
import type {CalendarViewType} from "../calendar/view/CalendarViewModel"
import type {CredentialsStorage, PersistentCredentials} from "./credentials/CredentialsProvider"
import type {CredentialEncryptionMode} from "./credentials/CredentialEncryptionMode"
import {assertMainOrNodeBoot} from "../api/common/Env"
import {PersistedAssignmentData, UsageTestStorage} from "./UsageTestModel"

assertMainOrNodeBoot()
export const defaultThemeId: ThemeId = "light"

/**
 * Device config for internal user auto login. Only one config per device is stored.
 */
export class DeviceConfig implements CredentialsStorage, UsageTestStorage {
	static readonly Version = 3
	static readonly LocalStorageKey = "tutanotaConfig"

	private _storage: Pick<Storage, "getItem" | "setItem"> | null
	private _config: {
		_version: number
		_credentials: Map<Id, PersistentCredentials>
		_scheduledAlarmUsers: Id[]
		_themeId: ThemeId
		_language: LanguageCode | null
		_defaultCalendarView: Record<Id, CalendarViewType | null>
		_hiddenCalendars: Record<Id, Id[]>
		_signupToken: string
		_credentialEncryptionMode: CredentialEncryptionMode | null
		_encryptedCredentialsKey: Base64 | null
		_testDeviceId: string | null
		_testAssignments: PersistedAssignmentData | null
		[key: string]: any
	}

	constructor(version: number, storage: Pick<Storage, "getItem" | "setItem"> | null) {
		this._storage = storage
		this._config = this._createDefaultConfig(version)
		this._load()
	}

	private _createDefaultConfig(version: number) {
		return {
			_version: version,
			_credentials: new Map<Id, PersistentCredentials>(),
			_scheduledAlarmUsers: [],
			_themeId: defaultThemeId,
			_language: null,
			_defaultCalendarView: {},
			_hiddenCalendars: {},
			_signupToken: "",
			_credentialEncryptionMode: null,
			_encryptedCredentialsKey: null,
			_testDeviceId: null,
			_testAssignments: null,
		}
	}

	store(persistentCredentials: PersistentCredentials): void {
		const userId = persistentCredentials.credentialInfo.userId
		const existing = this._config._credentials.get(userId)

		if (existing && existing.databaseKey !== null && existing.databaseKey !== undefined) {
			persistentCredentials.databaseKey = existing.databaseKey
		}

		this._config._credentials.set(userId, persistentCredentials)
		this.writeToStorage()
	}

	loadByUserId(userId: Id): PersistentCredentials | null {
		return this._config._credentials.get(userId) ?? null
	}

	loadAll(): Array<PersistentCredentials> {
		return Array.from(this._config._credentials.values())
	}

	deleteByUserId(userId: Id): void {
		if (this._config._credentials.delete(userId)) {
			this.writeToStorage()
		}
	}

	_load(): void {
		this._config = this._createDefaultConfig(this._config._version)

		let loadedConfig: any | null = null
		try {
			const loadedConfigString = this._storage?.getItem(DeviceConfig.LocalStorageKey) ?? null
			loadedConfig = loadedConfigString != null ? this._parseConfig(loadedConfigString) : null
		} catch (_e) {
			// Storage may be unavailable or throw when cookies are disabled.
		}

		let shouldWrite = false
		if (loadedConfig) {
			const loadedVersion = loadedConfig._version
			if (typeof loadedVersion !== "number" || loadedVersion <= this._config._version) {
				// Current-version data is checked too, so a legacy credential array or
				// incorrectly keyed credential object is normalized just once.
				shouldWrite = migrateConfig(loadedConfig, this._config._version)
			}

			this._config = {
				...this._config,
				...loadedConfig,
				_credentials: new Map(
					loadedConfig._credentials && !Array.isArray(loadedConfig._credentials)
						? Object.entries(loadedConfig._credentials) as Array<[Id, PersistentCredentials]>
						: [],
				),
			}
		}

		if (typeof this._config._signupToken !== "string" || this._config._signupToken.length === 0) {
			this._config._signupToken = this._createSignupToken()
			shouldWrite = true
		}

		if (shouldWrite) {
			this.writeToStorage()
		}
	}

	private _createSignupToken(): string {
		const bytes = new Uint8Array(6)
		let filled = false
		try {
			const cryptoProvider = typeof window !== "undefined" ? window.crypto : globalThis.crypto
			if (cryptoProvider?.getRandomValues) {
				cryptoProvider.getRandomValues(bytes)
				filled = true
			}
		} catch (_e) {
			// Fall back to a random token if the platform crypto API is unavailable.
		}
		if (!filled) {
			for (let i = 0; i < bytes.length; i++) {
				bytes[i] = Math.floor(Math.random() * 256)
			}
		}
		return uint8ArrayToBase64(bytes)
	}

	_parseConfig(loadedConfigString: string): any | null {
		try {
			const parsed = JSON.parse(loadedConfigString)
			return parsed != null && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null
		} catch (_e) {
			return null
		}
	}

	getSignupToken(): string {
		return this._config._signupToken
	}

	hasScheduledAlarmsForUser(userId: Id): boolean {
		return this._config._scheduledAlarmUsers.includes(userId)
	}

	setAlarmsScheduledForUser(userId: Id, setScheduled: boolean) {
		const scheduledIndex = this._config._scheduledAlarmUsers.indexOf(userId)
		const scheduledSaved = scheduledIndex !== -1

		if (setScheduled && !scheduledSaved) {
			this._config._scheduledAlarmUsers.push(userId)
			this.writeToStorage()
		} else if (!setScheduled && scheduledSaved) {
			this._config._scheduledAlarmUsers.splice(scheduledIndex, 1)
			this.writeToStorage()
		}
	}

	setNoAlarmsScheduled() {
		if (this._config._scheduledAlarmUsers.length > 0) {
			this._config._scheduledAlarmUsers = []
			this.writeToStorage()
		}
	}

	getLanguage(): LanguageCode | null {
		return this._config._language
	}

	setLanguage(language: LanguageCode | null) {
		if (this._config._language !== language) {
			this._config._language = language
			this.writeToStorage()
		}
	}

	writeToStorage(): void {
		try {
			const serializedConfig = JSON.stringify(this._config, (key, value) => {
				if (key === "_credentials") {
					return Object.fromEntries(this._config._credentials.entries())
				}
				return value
			})
			this._storage?.setItem(DeviceConfig.LocalStorageKey, serializedConfig)
		} catch (e) {
			// May occur when storage is disabled or full.
			console.log("could not store config", e)
		}
	}

	getTheme(): ThemeId {
		return this._config._themeId
	}

	setTheme(theme: ThemeId) {
		if (this._config._themeId !== theme) {
			this._config._themeId = theme
			this.writeToStorage()
		}
	}

	getDefaultCalendarView(userId: Id): CalendarViewType | null {
		return this._config._defaultCalendarView[userId]
	}

	setDefaultCalendarView(userId: Id, defaultView: CalendarViewType) {
		if (this._config._defaultCalendarView[userId] !== defaultView) {
			this._config._defaultCalendarView[userId] = defaultView
			this.writeToStorage()
		}
	}

	getHiddenCalendars(user: Id): Id[] {
		return this._config._hiddenCalendars.hasOwnProperty(user) ? this._config._hiddenCalendars[user] : []
	}

	setHiddenCalendars(user: Id, calendars: Id[]) {
		if (this._config._hiddenCalendars[user] !== calendars) {
			this._config._hiddenCalendars[user] = calendars
			this.writeToStorage()
		}
	}

	getCredentialEncryptionMode(): CredentialEncryptionMode | null {
		return this._config._credentialEncryptionMode
	}

	setCredentialEncryptionMode(encryptionMode: CredentialEncryptionMode | null) {
		if (this._config._credentialEncryptionMode !== encryptionMode) {
			this._config._credentialEncryptionMode = encryptionMode
			this.writeToStorage()
		}
	}

	getCredentialsEncryptionKey(): Uint8Array | null {
		return this._config._encryptedCredentialsKey ? base64ToUint8Array(this._config._encryptedCredentialsKey) : null
	}

	setCredentialsEncryptionKey(value: Uint8Array | null) {
		const encryptedKey = value ? uint8ArrayToBase64(value) : null
		if (this._config._encryptedCredentialsKey !== encryptedKey) {
			this._config._encryptedCredentialsKey = encryptedKey
			this.writeToStorage()
		}
	}

	async getTestDeviceId(): Promise<string | null> {
		return this._config._testDeviceId
	}

	async storeTestDeviceId(testDeviceId: string): Promise<void> {
		if (this._config._testDeviceId !== testDeviceId) {
			this._config._testDeviceId = testDeviceId
			this.writeToStorage()
		}
	}

	async getAssignments(): Promise<PersistedAssignmentData | null> {
		return this._config._testAssignments
	}

	async storeAssignments(persistedAssignmentData: PersistedAssignmentData): Promise<void> {
		if (this._config._testAssignments !== persistedAssignmentData) {
			this._config._testAssignments = persistedAssignmentData
			this.writeToStorage()
		}
	}
}

/**
 * Migrate an older device config in place. The return value indicates whether
 * the stored representation changed and therefore needs to be written.
 */
export function migrateConfig(loadedConfig: any, targetVersion: number = DeviceConfig.Version): boolean {
	if (loadedConfig == null || typeof loadedConfig !== "object") {
		return false
	}

	const loadedVersion = typeof loadedConfig._version === "number" ? loadedConfig._version : 0
	if (loadedVersion > targetVersion) {
		return false
	}

	let changed = false
	if (loadedVersion < 2) {
		if (loadedConfig._credentials == null) {
			loadedConfig._credentials = []
		}
		changed = true
	}
	if (loadedVersion < 3) {
		migrateConfigV2to3(loadedConfig)
		changed = true
	}

	if (Array.isArray(loadedConfig._credentials)) {
		const credentialsByUserId: Record<string, PersistentCredentials> = {}
		for (const credentials of loadedConfig._credentials) {
			const userId = credentials?.credentialInfo?.userId ?? credentials?.userId
			if (userId != null) {
				credentialsByUserId[userId] = credentials
			}
		}
		loadedConfig._credentials = credentialsByUserId
		changed = true
	} else if (loadedConfig._credentials != null && typeof loadedConfig._credentials === "object") {
		const credentialsByUserId: Record<string, PersistentCredentials> = {}
		for (const [storedUserId, credentials] of Object.entries(loadedConfig._credentials)) {
			const userId = (credentials as PersistentCredentials)?.credentialInfo?.userId ?? storedUserId
			credentialsByUserId[userId] = credentials as PersistentCredentials
			if (userId !== storedUserId) {
				changed = true
			}
		}
		if (changed) {
			loadedConfig._credentials = credentialsByUserId
		}
	}

	if (loadedVersion < targetVersion) {
		loadedConfig._version = targetVersion
		changed = true
	}
	return changed
}

/**
 * Migrate the credential fields from V2 to V3.
 *
 * Exported for testing.
 */
export function migrateConfigV2to3(loadedConfig: any) {
	const oldCredentialsArray = loadedConfig._credentials
	if (!Array.isArray(oldCredentialsArray)) {
		return
	}

	for (let i = 0; i < oldCredentialsArray.length; ++i) {
		const oldCredential = oldCredentialsArray[i]
		// Credentials already in V3 form are left intact, making migration idempotent.
		if (oldCredential?.credentialInfo) {
			continue
		}

		const mailAddress = typeof oldCredential?.mailAddress === "string" ? oldCredential.mailAddress : ""
		const isInternalUser = mailAddress.includes("@")
		const migratedCredential: any = {...oldCredential}
		delete migratedCredential.mailAddress
		delete migratedCredential.userId
		migratedCredential.credentialInfo = {
			login: isInternalUser ? mailAddress : oldCredential.userId,
			userId: oldCredential.userId,
			type: isInternalUser ? "internal" : "external",
		}
		oldCredentialsArray[i] = migratedCredential
	}
}

function getLocalStorage(): Storage | null {
	try {
		return client.localStorage() ? localStorage : null
	} catch (_e) {
		return null
	}
}

export const deviceConfig: DeviceConfig = new DeviceConfig(DeviceConfig.Version, getLocalStorage())
